// Keeps the sheet rows marked ThisWeek = TRUE and normalises them into dishes.
// Header matching is case- and space-insensitive, so "Photo URL", "photourl"
// and "PhotoUrl" all resolve to the same column.
const cfg = $('Config').first().json;
const rows = $input.all().map((i) => i.json);

const truthy = (v) => ['true', 'yes', 'y', '1', 'x'].includes(String(v ?? '').trim().toLowerCase());
const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const field = (row, name) => {
  const want = norm(name);
  for (const key of Object.keys(row)) if (norm(key) === want) return row[key];
  return undefined;
};

const marked = rows.filter((r) => truthy(field(r, 'ThisWeek')));
if (!marked.length) {
  throw new Error('No rows have ThisWeek = TRUE in the menu sheet. Mark 1-5 dishes and run again. Expected columns: Dish, Description, Price, PhotoUrl, ThisWeek.');
}

const maxDishes = Math.max(1, Math.min(5, Number(cfg.maxDishes ?? 5)));
const dishes = marked.slice(0, maxDishes).map((r) => ({
  name: String(field(r, 'Dish') ?? '').trim(),
  description: String(field(r, 'Description') ?? '').trim(),
  price: String(field(r, 'Price') ?? '').trim(),
  photo: String(field(r, 'PhotoUrl') ?? '').trim(),
}));

const missing = dishes.findIndex((d) => !d.name);
if (missing !== -1) throw new Error('Marked row ' + (missing + 1) + ' has an empty Dish cell.');

return [{ json: { dishes, totalMarked: marked.length, skipped: Math.max(0, marked.length - maxDishes) } }];

// Builder for the "Restaurant weekly specials" Zvid project.
// Adapted from the local-menu-promo / pro-local-menu-promo / local-top-5-dishes
// library examples: full-bleed sizzle hook, one photo card per dish, CTA endcard.
// The EXACT same logic is embedded in the n8n workflow's "Build project JSON"
// code node — keep the two in sync.

// ---------- tiny helpers -------------------------------------------------
const escapeHtml = (s) =>
  String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const round = (n) => Math.round(n * 100) / 100;

const hexToRgba = (hex, a) => {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex).trim());
  if (!m) return `rgba(232,106,51,${a})`;
  const n = parseInt(m[1], 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
};

const lighten = (hex, amt) => {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex).trim());
  if (!m) return hex;
  const n = parseInt(m[1], 16);
  const ch = (v) => Math.max(0, Math.min(255, v + amt)).toString(16).padStart(2, '0');
  return `#${ch((n >> 16) & 255)}${ch((n >> 8) & 255)}${ch(n & 255)}`;
};

// Auto week label: "WEEK OF JUL 27" for the Monday of the current week.
const autoWeekLabel = (now = new Date()) => {
  const d = new Date(now.getTime());
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); // back to Monday
  const months = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
  return `WEEK OF ${months[d.getMonth()]} ${d.getDate()}`;
};

// ---------- main ---------------------------------------------------------
function buildProject(cfg, dishesInput) {
  const bg = cfg.brandBg || '#180F0A';
  const accent = cfg.brandAccent || '#E86A33';
  const cream = cfg.brandCream || '#FFF4E8';
  const muted = cfg.brandMuted || '#E4CBB0';
  const headFont = cfg.headlineFont || 'Bebas Neue';
  const bodyFont = cfg.bodyFont || 'DM Sans';

  const maxDishes = Math.max(1, Math.min(5, Number(cfg.maxDishes ?? 5)));

  // -- dishes: validate, trim, fall back ---------------------------------
  const fallbacks = Array.isArray(cfg.fallbackDishPhotos) ? cfg.fallbackDishPhotos.filter(Boolean) : [];
  const raw = Array.isArray(dishesInput) ? dishesInput : [];
  const dishes = raw
    .map((d) => ({
      name: String(d.name ?? '').trim(),
      description: String(d.description ?? '').trim(),
      price: String(d.price ?? '').trim(),
      photo: String(d.photo ?? '').trim(),
    }))
    .filter((d) => d.name);

  if (!dishes.length) {
    throw new Error(
      'No dishes to feature. Mark 1-5 rows with ThisWeek = TRUE in the menu sheet (columns: Dish, Description, Price, PhotoUrl, ThisWeek).'
    );
  }
  const skipped = Math.max(0, dishes.length - maxDishes);
  const picked = dishes.slice(0, maxDishes);

  picked.forEach((d, i) => {
    if (!/^https?:\/\//i.test(d.photo)) {
      d.photo = fallbacks.length ? fallbacks[i % fallbacks.length] : '';
    }
    if (!d.photo) throw new Error(`Dish "${d.name}" has no PhotoUrl and no fallback photo is configured.`);
    // Keep descriptions to ~3 lines on the card.
    if (d.description.length > 220) d.description = d.description.slice(0, 217).trimEnd() + '…';
  });

  const weekLabel = String(cfg.weekLabel || '').trim() || autoWeekLabel();

  // -- timing ------------------------------------------------------------
  const hookSeconds = Number(cfg.hookSeconds ?? 3);
  const dishSeconds = Number(cfg.dishSeconds ?? 2.8);
  const ctaSeconds = Number(cfg.ctaSeconds ?? 3.4);

  // -- adaptive font sizes (long names must not clip) --------------------
  const nameLen = (cfg.restaurantName || '').length;
  const brandFs = nameLen <= 20 ? 38 : nameLen <= 32 ? 31 : 26;
  const brandLs = nameLen <= 20 ? 10 : nameLen <= 32 ? 6 : 4;

  const hookTitle = cfg.hookTitle || "This week's specials";
  const hookFs = hookTitle.length <= 20 ? 132 : hookTitle.length <= 30 ? 106 : 86;

  const ctaHeadline = cfg.ctaHeadline || 'Hungry yet?';
  const ctaFs = ctaHeadline.length <= 14 ? 96 : ctaHeadline.length <= 24 ? 78 : 62;

  const dishNameFs = (n) => (n.length <= 16 ? 104 : n.length <= 26 ? 88 : n.length <= 40 ? 72 : 58);

  const accentBorder = hexToRgba(accent, 0.4);
  const accentSoft = hexToRgba(accent, 0.7);

  // -- SVG overlays ------------------------------------------------------
  const hookSvg =
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<defs><linearGradient id='rwsHook' x1='0' y1='0' x2='0' y2='1'>` +
    `<stop offset='0' stop-color='${bg}' stop-opacity='0.55'/>` +
    `<stop offset='0.42' stop-color='${bg}' stop-opacity='0.12'/>` +
    `<stop offset='0.68' stop-color='${bg}' stop-opacity='0.5'/>` +
    `<stop offset='1' stop-color='${bg}' stop-opacity='0.92'/>` +
    `</linearGradient></defs>` +
    `<rect width='1080' height='1920' fill='url(#rwsHook)'/>` +
    `<path d='M84 300 L84 116 L268 116' fill='none' stroke='${cream}' stroke-width='9' stroke-opacity='0.9'/>` +
    `<path d='M996 1624 L996 1808 L812 1808' fill='none' stroke='${accent}' stroke-width='9'/>` +
    `<circle cx='940' cy='300' r='7' fill='${accent}'/>` +
    `</svg>`;

  const dishSvg = (idx) =>
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<defs><linearGradient id='rwsDish${idx}' x1='0' y1='0' x2='0' y2='1'>` +
    `<stop offset='0' stop-color='${bg}' stop-opacity='0.42'/>` +
    `<stop offset='0.4' stop-color='${bg}' stop-opacity='0.06'/>` +
    `<stop offset='0.68' stop-color='${bg}' stop-opacity='0.55'/>` +
    `<stop offset='1' stop-color='${bg}' stop-opacity='0.96'/>` +
    `</linearGradient></defs>` +
    `<rect width='1080' height='1920' fill='url(#rwsDish${idx})'/>` +
    `<rect x='46' y='46' width='988' height='1828' rx='30' fill='none' stroke='${accentBorder}' stroke-width='1.5'/>` +
    `</svg>`;

  const ctaSvg =
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<defs><radialGradient id='rwsCta' cx='0.5' cy='0.4' r='0.9'>` +
    `<stop offset='0' stop-color='${lighten(bg, 22)}'/>` +
    `<stop offset='1' stop-color='${bg}'/>` +
    `</radialGradient></defs>` +
    `<rect width='1080' height='1920' fill='url(#rwsCta)'/>` +
    `<rect x='46' y='46' width='988' height='1828' rx='34' fill='none' stroke='${accentBorder}' stroke-width='2'/>` +
    `<path d='M470 560 C470 610 610 610 610 560 M450 560 H630 L610 760 C608 780 472 780 470 760 Z' fill='none' stroke='${accent}' stroke-width='7' stroke-linejoin='round'/>` +
    `<path d='M505 500 C505 480 520 480 520 460 M545 500 C545 480 560 480 560 460 M585 500 C585 480 600 480 600 460' stroke='${accentSoft}' stroke-width='6' stroke-linecap='round' fill='none'/>` +
    `</svg>`;

  // -- scene 1: sizzle hook ----------------------------------------------
  const scenes = [];
  scenes.push({
    id: 'hook',
    duration: hookSeconds,
    backgroundColor: bg,
    transition: 'fade',
    transitionId: 'dish-1',
    transitionDuration: 0.5,
    visuals: [
      {
        type: 'VIDEO',
        src: cfg.sizzleVideo,
        width: 1080,
        height: 1920,
        position: 'center-center',
        resize: 'cover',
        volume: 0,
        track: 0,
        enterBegin: 0,
        exitEnd: hookSeconds,
      },
      { type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: hookSeconds, svg: hookSvg },
      {
        type: 'TEXT',
        x: 540,
        y: 150,
        width: 940,
        anchor: 'top-center',
        track: 2,
        enterBegin: 0.2,
        enterEnd: 0.6,
        enterAnimation: 'fade',
        exitEnd: hookSeconds,
        style: { fontFamily: headFont, color: cream },
        html: `<div style='text-align:center; color:${cream}; font-size:${brandFs}px; letter-spacing:${brandLs}px;'>${escapeHtml(cfg.restaurantName)}</div>`,
      },
      {
        type: 'TEXT',
        x: 90,
        y: 1500,
        width: 900,
        anchor: 'bottom-left',
        track: 3,
        enterBegin: 0.4,
        enterEnd: 0.85,
        enterAnimation: 'smoothup',
        exitEnd: hookSeconds,
        style: { fontFamily: headFont, color: cream },
        html:
          `<div style='display:inline-block; background:${accent}; color:${cream}; border-radius:999px; padding:14px 34px; font-size:27px; font-weight:800; letter-spacing:4px; font-family:${bodyFont}, sans-serif;'>${escapeHtml(weekLabel)}</div>` +
          `<div style='margin-top:26px; color:${cream}; font-size:${hookFs}px; line-height:0.98; letter-spacing:2px;'>${escapeHtml(hookTitle)}</div>`,
      },
      {
        type: 'TEXT',
        x: 90,
        y: 1560,
        width: 900,
        anchor: 'top-left',
        track: 4,
        enterBegin: 0.65,
        enterEnd: 1.1,
        enterAnimation: 'smoothup',
        exitEnd: hookSeconds,
        style: { fontFamily: bodyFont, color: muted },
        html: `<div style='color:${muted}; font-size:${(cfg.tagline || '').length > 60 ? 26 : 30}px; line-height:1.35; font-weight:600;'>${escapeHtml(cfg.tagline || '')}</div>`,
      },
    ],
  });

  // -- one card per dish --------------------------------------------------
  picked.forEach((dish, i) => {
    const idx = i + 1;
    const isLast = i === picked.length - 1;
    const counter = picked.length > 1 ? `SPECIAL ${idx} OF ${picked.length}` : "THIS WEEK'S SPECIAL";
    const priceFs = dish.price.length > 7 ? 34 : 40;

    const visuals = [
      {
        type: 'IMAGE',
        src: dish.photo,
        width: 1080,
        height: 1920,
        position: 'center-center',
        resize: 'cover',
        zoom: true,
        track: 0,
        enterBegin: 0,
        exitEnd: dishSeconds,
      },
      { type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: dishSeconds, svg: dishSvg(idx) },
      {
        type: 'TEXT',
        x: 90,
        y: 150,
        anchor: 'top-left',
        track: 2,
        enterBegin: 0.15,
        enterEnd: 0.5,
        enterAnimation: 'smoothleft',
        exitEnd: dishSeconds,
        style: { fontFamily: bodyFont, color: cream },
        html: `<div style='display:inline-block; background:${accent}; color:${cream}; border-radius:999px; padding:14px 34px; font-size:26px; font-weight:800; letter-spacing:3px;'>${escapeHtml(counter)}</div>`,
      },
      {
        type: 'TEXT',
        x: 90,
        y: 1620,
        width: 900,
        anchor: 'bottom-left',
        track: 3,
        enterBegin: 0.35,
        enterEnd: 0.8,
        enterAnimation: 'smoothup',
        exitEnd: dishSeconds,
        style: { fontFamily: headFont, color: cream },
        html:
          `<div style='color:${cream}; font-size:${dishNameFs(dish.name)}px; line-height:0.98; letter-spacing:2px;'>${escapeHtml(dish.name)}</div>` +
          (dish.description
            ? `<div style='margin-top:16px; font-family:${bodyFont}, sans-serif; color:${muted}; font-size:29px; line-height:1.42; font-weight:500;'>${escapeHtml(dish.description)}</div>`
            : ''),
      },
    ];

    if (dish.price) {
      visuals.push({
        type: 'TEXT',
        x: 880,
        y: 205,
        anchor: 'center-center',
        angle: -6,
        track: 4,
        enterBegin: 0.55,
        enterEnd: 0.9,
        enterAnimation: 'circleopen',
        exitEnd: dishSeconds,
        style: { fontFamily: bodyFont, color: cream },
        html: `<div style='display:inline-block; background:${cream}; color:${bg}; border-radius:18px; padding:14px 36px; font-size:${priceFs}px; font-weight:800;'>${escapeHtml(dish.price)}</div>`,
      });
    }

    scenes.push({
      id: `dish-${idx}`,
      duration: dishSeconds,
      backgroundColor: bg,
      transition: isLast ? 'smoothup' : 'fade',
      transitionId: isLast ? 'cta' : `dish-${idx + 1}`,
      transitionDuration: isLast ? 0.5 : 0.45,
      visuals,
    });
  });

  // -- CTA endcard ---------------------------------------------------------
  const ctaVisuals = [
    { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: ctaSeconds, svg: ctaSvg },
    {
      type: 'TEXT',
      x: 540,
      y: 900,
      width: 940,
      anchor: 'top-center',
      track: 1,
      enterBegin: 0.25,
      enterEnd: 0.7,
      enterAnimation: 'smoothup',
      exitEnd: ctaSeconds,
      style: { fontFamily: headFont, color: cream },
      html: `<div style='text-align:center; color:${cream}; font-size:${ctaFs}px; line-height:1; letter-spacing:2px;'>${escapeHtml(ctaHeadline)}</div>`,
    },
    {
      type: 'TEXT',
      x: 540,
      y: 1120,
      anchor: 'top-center',
      track: 2,
      enterBegin: 0.65,
      enterEnd: 1.05,
      enterAnimation: 'circleopen',
      exitEnd: ctaSeconds,
      style: { fontFamily: bodyFont, color: cream },
      html: `<div style='display:inline-block; background:${accent}; color:${cream}; border-radius:999px; padding:26px 62px; font-size:36px; font-weight:800;'>${escapeHtml(cfg.ctaText || 'Book a table')}</div>`,
    },
    {
      type: 'TEXT',
      x: 540,
      y: 1300,
      width: 900,
      anchor: 'top-center',
      track: 3,
      enterBegin: 0.95,
      enterEnd: 1.35,
      enterAnimation: 'fade',
      exitEnd: ctaSeconds,
      style: { fontFamily: bodyFont, color: cream },
      html:
        `<div style='text-align:center; color:${cream}; font-size:30px; font-weight:700;'>${escapeHtml(cfg.handle || '')}</div>` +
        `<div style='margin-top:10px; text-align:center; color:${muted}; font-size:26px; font-weight:500;'>${escapeHtml(cfg.address || '')}</div>`,
    },
    {
      type: 'TEXT',
      x: 540,
      y: 1460,
      width: 900,
      anchor: 'top-center',
      track: 4,
      enterBegin: 1.15,
      enterEnd: 1.55,
      enterAnimation: 'fade',
      exitEnd: ctaSeconds,
      style: { fontFamily: headFont, color: cream },
      html: `<div style='text-align:center; color:${hexToRgba(cream, 0.55)}; font-size:25px; letter-spacing:6px;'>${escapeHtml(cfg.deliveryNote || '')}</div>`,
    },
  ];

  scenes.push({ id: 'cta', duration: ctaSeconds, backgroundColor: bg, visuals: ctaVisuals });

  // -- assemble -----------------------------------------------------------
  const overlaps = scenes.reduce((s, sc) => s + (sc.transitionDuration || 0), 0);
  const totalDuration = round(scenes.reduce((s, sc) => s + sc.duration, 0) - overlaps);

  // The API accepts ASCII letters/digits/space/_/- only in project names.
  const safeName =
    (String(cfg.restaurantName || 'restaurant')
      .toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 44) || 'restaurant') + '-weekly-specials';

  const payload = {
    name: safeName,
    resolution: cfg.resolution || 'instagram-reel',
    frameRate: Number(cfg.frameRate ?? 30),
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes,
    // NOTE: no `track` on audios — the public API rejects it.
    audios: cfg.musicUrl ? [{ src: cfg.musicUrl, volume: Number(cfg.musicVolume ?? 0.18) }] : [],
  };

  return {
    payload,
    meta: {
      weekLabel,
      dishCount: picked.length,
      skippedDishes: skipped,
      dishNames: picked.map((d) => d.name),
      totalDuration,
      sceneBreakdown: scenes.map((s, i) => `${i + 1}. ${s.id} — ${s.duration}s`).join('\n'),
    },
  };
}

const cfg = $('Config').first().json;
const picked = $('Pick weekly dishes').first().json;
const { payload, meta } = buildProject(cfg, picked.dishes);
return [{ json: { payload, meta: { ...meta, skippedRows: picked.skipped ?? 0, totalMarked: picked.totalMarked ?? meta.dishCount } } }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// draft, then set dryRun to false in Config to go live.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

const sceneBreakdown = d.payload.scenes.map((s, i) => (i + 1) + '. ' + s.id + ' — ' + s.duration + 's').join('\n');

return [{
  json: {
    dryRun: true,
    weekLabel: d.meta.weekLabel,
    dishes: d.meta.dishNames,
    dishCount: d.meta.dishCount,
    skippedRows: d.meta.skippedRows,
    videoSeconds: d.meta.totalDuration,
    creditsRequired: d.creditsRequired,
    warnings: d.warnings,
    editorLink,
    draftId,
    sceneBreakdown,
    nextStep: editorLink
      ? 'Open editorLink to preview and tweak the draft. Set dryRun to false in Config to render.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// Final report for the run: the finished video URL plus a caption you can
// paste straight into Instagram or Facebook.
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result && job.result.url) || null;

const caption =
  build.meta.weekLabel + ' at ' + cfg.restaurantName + ' — ' +
  build.meta.dishNames.join(' · ') + '. ' + (cfg.ctaText || 'Book a table') + '! ' + (cfg.handle || '');

return [{
  json: {
    videoUrl: url,
    jobId: job.id,
    creditsCharged: build.creditsRequired,
    weekLabel: build.meta.weekLabel,
    dishes: build.meta.dishNames,
    dishCount: build.meta.dishCount,
    videoSeconds: build.meta.totalDuration,
    suggestedCaption: caption.trim(),
    nextStep: 'Post videoUrl to Instagram Reels / your Facebook Page — see the Publish sticky note for the exact endpoints.',
  },
}];
